/** Levels 4–5 — descriptive statistics, visual analysis, machine-learning models and their evaluation. */
import { pct, num, step, inp, safe } from './_helpers.js';
const parseList = (s) => String(s).split(/[,\s]+/).map(Number).filter(n => !Number.isNaN(n));
const mean = (a) => a.reduce((s, x) => s + x, 0) / a.length;
const sd = (a) => { const m = mean(a); return Math.sqrt(a.reduce((s, x) => s + (x - m) ** 2, 0) / (a.length - 1)); };
const list = (key, label, value) => ({ key, label, value, type: 'list' });
const ln = Math.log;

